-- ueberlauf_position
update public.fields set verification_status='verified_against_standard', verification_quote='Überlaufeinrichtungen dienen der kontrollierten Ableitung des Überschusswassers. Diese sind unter Beachtung der Bemessungsnormen so zu planen und anzuordnen, dass Niederschläge und zulaufendes Wasser über den maximalen Wasserstand hinaus sicher abgeleitet werden. Die Ableitung kann über den Gewässerrand und/oder über technische Überlaufeinrichtungen erfolgen. Die Höhe der Überlaufeinrichtung wird durch den geplanten maximalen Wasserstand vorgegeben. — printed p.32 | Der Notüberlauf ist als kanalunabhängige Notentwässerung höher als der Regelüberlauf einzubauen. — printed p.132', verification_note='md-verified 2026-09-05 (§4.10 p.32, Anhang 1 p.132) [VC]; clause_reference §6 is wrong → §4.10', verified_at=now() where id='079fed2d-0004-46ba-9e95-8c97c8e5d4a3' and verification_status not in ('verified_against_standard','corrected');

