update public.fields set verification_status='verified_against_standard', verification_quote='Bei Kunststoff- und Elastormerbahnen ist an den Längs- und Quernähten eine Mindestbreite der Überlappung von 40 mm einzuhalten. Bei Bahnen mit Polymerbitumenbeschichtung ist eine Mindestbreite von 60 mm einzuhalten. — printed p.85 | Auf der Baustelle ausgeführte Naht- und Stoßverbindungen sind auf ihre Dichtheit zu prüfen. Hierfür ist eine Kombination aus mindestens zwei der nachstehend aufgeführten Prüfverfahren gemäß DIN 18535-2 anzuwenden: mechanische Prüfung (z. B. Reißnadel); optische Prüfung; Anblasprüfung; Vakuumprüfung. — printed p.86', verification_note='md-verified 2026-09-05 (§6.2.2.1, printed p.85-86) [VC]', verified_at=now() where id='fe9a88d1-2719-4b69-b4bd-1d1bc098da82' and verification_status not in ('verified_against_standard','corrected');

