-- fk_haftung_untergrund (obligation only; no N/mm² adhesion value printed)
update public.fields set verification_status='verified_against_standard', verification_quote='Der Untergrund (z. B. Bitumen- und Kunststoffbahnen, bitumenhaltige, zementgebundene und kunststoffgebundene Baustoffe, Metalle, Holz, Naturstein) muss bezüglich seiner Festigkeit und Oberflächenbeschaffenheit als Kontaktfläche für die Abdichtung geeignet sein. Dazu ist dieser in geeigneter Art vorzubereiten und ggf. durch eine Grundierung zu behandeln. Zur Vermeidung der Hinterläufigkeit ist ein vollflächiger Haftungsverbund zum Untergrund herzustellen. — printed p.89', verification_note='md-verified 2026-09-05 (§6.3.2, printed p.89) [VC]; clause_reference §9.9 does not exist → §6.3.2; no numeric adhesion (N/mm²) printed — the number is EKOWAI''s', verified_at=now() where id='8da120af-8701-4608-be64-735136a7bd73' and verification_status not in ('verified_against_standard','corrected');

-- fk_uv_bestaendigkeit
