-- ---------- FLL-GAR-19 Stahl ----------

-- stahl_typ (6 enum values = the six steels named in §7.1.1.1)
update public.fields set verification_status='verified_against_standard', verification_quote='Bevorzugt zu verwenden sind daher nicht rostende Stähle V2A (Werkstoffnummer 1.4301), da diese Edelstähle beständig gegen Trinkwasser sind. [...] Bei höheren Anforderungen an die Korrosionsbeständigkeit (z. B. in Meeresnähe oder in Industrieatmosphäre) sind rostfreie Stähle V4A (Werkstoffnummer 1.4401) zu verwenden. Bei Kontakt mit Meerwasser oder für ähnliche Einsatzzwecke (z. B. Solebecken) sind noch höherwertige Stähle, wie z. B. V5A (Werkstoffnummer 1.4539) zu verwenden. Darüber hinaus können nicht rostende, wetterfeste Baustähle verwendet werden. Für dünnere Produktstärken bis 12,5 mm steht Stahl der Werkstoffnummer 1.8946 (z. B. COR-TEN A) zur Verfügung. Für dickere Produktstärken bis über 50 mm wird Werkstoffnummer 1.8965 (z. B. COR-TEN B) eingesetzt. [...] Unlegierte Stähle müssen verzinkt und ggf. beschichtet werden, um eine Korrosion zu verhindern. — printed p.101', verification_note='md-verified 2026-09-05 (§7.1.1.1, printed p.101) [VC]', verified_at=now() where id='9a726196-893f-4fd5-afcd-c2a825ec6909' and verification_status not in ('verified_against_standard','corrected');

-- verzinkung_dicke_um ("soll" ≥ 100 μm; not gated)
update public.fields set verification_status='verified_against_standard', verification_quote='Unlegierte Stähle müssen verzinkt und ggf. beschichtet werden, um eine Korrosion zu verhindern. Durch Schmelztauchen (Feuerverzinken) soll eine Schichtstärke von wenigstens 100 μm erreicht werden. Einen zusätzlichen Schutz für unlegierte Stähle bietet die Beschichtung nach der Verzinkung. [...] Empfehlenswert sind jedoch zwei Voranstriche und drei Deckanstriche, um eine Beschichtungsstärke von wenigstens 320 μm zu erreichen. — printed p.101', verification_note='md-verified 2026-09-05 (§7.1.1.1, printed p.101) [VC]; modal "soll"', verified_at=now() where id='b815422f-48b2-4b49-a45b-215a70df76ce' and verification_status not in ('verified_against_standard','corrected');

