update public.fields set verification_status='verified_against_standard', verification_quote='Die Abdichtung am Gewässerrand sollte i. d. R. im frei gestalteten Übergang zum angrenzenden Gelände dauerhaft mind. 5 cm höher sein als der vorgesehene Höchstwasserstand. Dies gilt auch für Schwimm- und Badeteiche. — printed p.32 | Die Oberkante der Abdichtung muss im frei gestalteten Übergang zum angrenzenden Gelände mind. 50 mm über dem geplanten Höchstwasserstand eingebaut werden. — printed p.117', verification_note='md-verified 2026-09-05 (§4.8 p.32, §9.1 p.117) [VC]', verified_at=now() where id='6dfb6931-5b1d-48be-a54f-476d6bedb9e4' and verification_status not in ('verified_against_standard','corrected');

