update public.fields set verification_status='verified_against_standard', verification_quote='An aufgehenden Bauteilen und Bauwerken ist die Oberkante der Abdichtung i. d. R. 30 cm über den geplanten Höchstwasserstand auszuführen. Durch Verwendung angepasster Randbefestigungen ist eine Reduzierung der Mindestüberhöhung der Abdichtung auf ≥ 15 cm möglich. — printed p.32 | Die Oberkante der Abdichtung ist an aufgehenden Bauteilen und Bauwerken i. d. R. 30 cm über den geplanten Höchstwasserstand auszuführen. Nur mit geeigneter Randbefestigung und Sicherung gegen Hinter- und Unterlaufen ist eine Reduzierung auf mind. 15 cm über Höchstwasserstand zugelassen. — printed p.117', verification_note='md-verified 2026-09-05 (§4.8 p.32, §9.1 p.117) [VC]', verified_at=now() where id='c0fcbcfa-a69f-44d4-9bd6-5321ba3a632a' and verification_status not in ('verified_against_standard','corrected');

