-- mit_bepflanzung
update public.fields set verification_status='verified_against_standard', verification_quote='Vorhandene und geplante Bepflanzung sowie Pflanz- und Pflegearbeiten dürfen die Funktion der Abdichtung nicht beeinträchtigen. Das Gefährdungspotential ist abhängig von den verwendeten Werkstoffen bzw. Produkten und ist im Durchwurzelungsverhalten und in der Ausbreitungsstrategie (z. B. Ausläufer) der Pflanzen begründet. — printed p.124 | Natrium-Wasserglas und Lithium-Wasserglas sind phytotoxisch; Kalium-Wasserglas ist pflanzenverträglich. — printed p.103', verification_note='md-verified 2026-09-05 (§10.1 p.124, §7.2 p.103) [VC]', verified_at=now() where id='cc71d336-630b-4ca7-b0d9-e994047bb0d0' and verification_status not in ('verified_against_standard','corrected');

-- bep_pflanzenarten
update public.fields set verification_status='verified_against_standard', verification_quote='Pflanzenarten mit starkem Rhizomwachstum (insbesondere monopodiale Bambusarten) sowie Pflanzen mit intensivem Wurzelwerk (insbesondere Großgehölze) können eine Durchwurzelung der Abdichtung bewirken. — printed p.125 | Tab. 29: Beispiele von Pflanzen mit aggressiven Wurzeln oder Rhizomen — Helophyten und Hydrophyten: Phragmites australis Gewöhnlicher Schilfrohr; Phalaris arundinacea Rohr-Glanzgras; Cyperus longus Langes Zyperngras; [...] Terrestrische Pflanzen: Phyllostachys spp. und andere rhizombildende Bambusse; Prunus spinosa Schlehe; Pyracantha coccinea Feuerdorn; [...] — printed p.125', verification_note='md-verified 2026-09-05 (§10.3 Tab.29, printed p.125) [VC]; clause_reference §12 is wrong → §10.3', verified_at=now() where id='bd1614e0-6da3-4263-99f8-f6bdf3bd52f1' and verification_status not in ('verified_against_standard','corrected');

