update public.fields set verification_status='verified_against_standard', verification_quote='Bei Verwendung oder Vorhandensein derartiger Pflanzenarten sind über den Standardaufbau der Abdichtung hinausgehende bauliche Vorkehrungen, z. B. als Rhizom- und Wurzelsperre, zu treffen und besondere Pflegemaßnahmen vorzusehen. — printed p.125 | Abdichtungen, die aufgrund ihrer werkstoffspezifischen Eigenschaften als wurzel- und rhizomfest gelten (z. B. Stahl, Beton, PEHD), erfordern keinen gesonderten Nachweis nach FLL-Prüfverfahren — printed p.126', verification_note='md-verified 2026-09-05 (§10.3 p.125, §10.4 p.126) [VC]; clause_reference §12 is wrong → §10.3/§10.4; duplicate of wurzel_rhizomfestigkeit_required (GAR-09)', verified_at=now() where id='f38a7cdb-3bfb-4b00-a1ad-0790f2fdbb22' and verification_status not in ('verified_against_standard','corrected');

-- bep_einbauten_typen
update public.fields set verification_status='verified_against_standard', verification_quote='Einbauten (z. B. Pflanztröge, Findlinge, Quellsteine sowie Fundamente von Stegen und Brücken) sowie die dafür notwendigen Ausführungs- und Wartungsarbeiten dürfen die Funktion der Abdichtung nicht beeinträchtigen. In Abhängigkeit vom Werkstoff der Abdichtung sowie der statischen und dynamischen Beanspruchung der Einbauten sind zusätzliche Schutzmaßnahmen vorzusehen (s. Abschnitte 8 und 9). — printed p.126', verification_note='md-verified 2026-09-05 (§10.5, printed p.126) [VC]; clause_reference §12 is wrong → §10.5', verified_at=now() where id='d2373428-0b78-48a1-85ab-b08ce8d67827' and verification_status not in ('verified_against_standard','corrected');

